    // including any delay() the repository calls.
    coEvery { api.fetch() } coAnswers {
        delay(2000)          // virtual, not real
        throw IOException("slow network")
    }
    coEvery { cache.get() } returns "cached"

    val result = repository.get()

    assertEquals("cached", result)
    // no Thread.sleep, no real elapsed time
